{"name":"solution.py","source":"#!/usr/bin/env python3
"""Convert a UTF-8 CSV with header item,quantity to a JSON array.

Normalizes item names (collapse whitespace, casefold), merges rows with the
same normalized name by summing quantities, and emits objects with exactly
item (string) and quantity (integer), sorted by normalized item name.
"""
import sys
import csv
import json
import re

QTY_RE = re.compile(r"^\d+$")


def normalize(name: str) -> str:
    """Collapse all whitespace to single spaces and casefold."""
    return " ".join(name.split()).casefold()


def main() -> int:
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        return 2

    path = sys.argv[1]
    with open(path, "r", encoding="utf-8", newline="") as f:
        rows = list(csv.reader(f))

    # Header-only or empty file -> empty array.
    if not rows:
        print(json.dumps([], ensure_ascii=False))
        return 0

    header = rows[0]
    idx = {}
    for i, col in enumerate(header):
        idx.setdefault(col.strip().casefold(), i)

    if "item" in idx and "quantity" in idx:
        i_item, i_qty = idx["item"], idx["quantity"]
    else:
        i_item, i_qty = 0, 1

    def field(row: list, i: int) -> str:
        return row[i] if i < len(row) else ""

    totals: dict[str, int] = {}
    for row in rows[1:]:
        if not row:
            continue
        name = normalize(field(row, i_item))
        if name == "":
            continue
        qraw = field(row, i_qty).strip()
        if qraw == "":
            q = 1
        elif QTY_RE.match(qraw):
            q = int(qraw, 10)
        else:
            # Not a valid nonnegative base-10 integer; skip defensively.
            continue
        totals[name] = totals.get(name, 0) + q

    out = [{"item": k, "quantity": v} for k, v in totals.items()]
    out.sort(key=lambda o: o["item"])
    print(json.dumps(out, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())"}

